<template>
  <div class="popup__content">
    <ClosureSvg class="popup__svg-closure" @click="$emit('closing')" />
    <div class="popup__icon">
      <img src="@/assets/AligoID.png" alt="Menu" />
    </div>

    <h2 class="popup__title">Введите код</h2>
    <p class="popup__paragraph">
      Вы собираетесь изменить настройки городов и регионов. Для подтверждения
      данного действия на номер ***18-18 отправлен проверочный код.
    </p>
    <AutosTextTemplate placeholder="Точное значение" />
    <p class="popup__paragraph">{{ countdownText }}</p>
  </div>
</template>
<script setup>
import { ref, onMounted, onUnmounted, defineProps } from 'vue';
import AutosTextTemplate from '@/components/UI/AutosTextTemplate';
import ClosureSvg from '@/assets/icons/close-gray';

const countdownText = ref('Получить новый можно через 2:00');

let intervalId = null;

function startCountdown(seconds = 120) {
  let remaining = seconds;

  updateText(remaining);

  intervalId = setInterval(() => {
    remaining--;
    if (remaining <= 0) {
      clearInterval(intervalId);
      countdownText.value = 'Можно получить новый код';
      return;
    }
    updateText(remaining);
  }, 1000);
}

function updateText(seconds) {
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  const paddedSecs = secs < 10 ? `0${secs}` : secs;
  countdownText.value = `Получить новый можно через ${mins}:${paddedSecs}`;
}

onMounted(() => {
  startCountdown(119); // 1:59
});

onUnmounted(() => {
  if (intervalId) clearInterval(intervalId);
});

defineProps({
  id: String,
  data: Object,
});
// emits: ['closing', 'success'],
</script>
<style scoped lang="scss">
.popup {
  &__content {
    justify-content: space-between;
  }
  &__icon {
    width: 152px;
    height: 32px;
    border: 1px solid #eeeeee;
    margin-bottom: 32px;
  }
  &__title {
    color: #323232;
    font-size: 16px;
    line-height: 20px;
    font-weight: 700;
    margin-bottom: 16px;
  }
  &__paragraph {
    font-size: 14px;
    line-height: 18px;
    margin-bottom: 16px;
  }
  .simple-input {
    margin-bottom: 16px;
  }
}
</style>
